import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("Claim Office", () => {
  describe("quote — base premiums (newcomer, first quote: +10% first insurance, +5 G fee)", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("plain sword → 100 base +10 first insurance +5 fee = 115 G");
    it.todo("plain amulet → 60 +6 +5 = 71 G");
    it.todo("plain staff → 80 +8 +5 = 93 G");
    it.todo("plain potion → 40 +4 +5 = 49 G");
    it.todo("1 rune → 25 +2.5 +5 = 32.5 → rounded up to 33 G");
    it.todo("2 runes → 50 G base → 60 G");
    it.todo("3 runes → 60 G base (block applies) → 71 G");
    it.todo("4 runes → 100 G base (no block, requires exactly 3) → 115 G");
    it.todo("7 runes → 175 G base → 197.5 rounded up to 198 G");
    it.todo("2 runes + 1 moonstone → 75 G base (different types, no block) → 88 G");
    it.todo("3 runes + 3 moonstones → 120 G base (two blocks) → 137 G");
    it.todo("unknown item type (broomstick) → throws");
  });

  describe("quote — premium modifiers", () => {
    it.todo("cursed sword (steel, enchantment 3), newcomer → 165 G");
    it.todo("sword with enchantment 4, not cursed → no surcharge → 115 G");
    it.todo("cursed sword with enchantment 4 → only curse surcharge → 165 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge → 145 G");
    it.todo("cursed sword with enchantment 5 → both surcharges → 195 G");
    it.todo("customer with 1 year → no loyalty discount → 115 G for plain sword");
    it.todo("customer with exactly 2 years → loyalty discount → 95 G for plain sword");
    it.todo("item surcharge applies only to the cursed item: cursed sword + plain amulet → 160 + 50 + 16 + 5 = 231 G");
    it.todo("second quote in scenario gets 15% follow-up discount: plain sword, 0 years → 100 G");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7, 3 years → 160 G");
  });

  describe("claim", () => {
    it.todo("schema example: amulet quote for 5-year customer → 59 G; amulet damage 200 → payout 100, remainingCap 1100");
    it.todo("regular steel sword enchantment 3, damage 500 → payout 400, remainingCap 1600");
    it.todo("rune damage 200 → payout 100, remainingCap 400");
    it.todo("dragon-material sword enchantment 8, damage 1000 → payout 400");
    it.todo("dragon-material sword enchantment 9, damage 1000 → payout 400 (50% rule wins)");
    it.todo("dragon-material sword enchantment 5, damage 800 → payout 700");
    it.todo("steel sword enchantment 9, damage 1000 → payout 400");
    it.todo("payout rounded down: steel sword enchantment 9, damage 901 → 350.5 → 350");
    it.todo("deductible per damaged item: sword 500 + amulet 300 → payout 600, remainingCap 2600 (cap 3200)");
    it.todo("two swords insured, both damaged 500 each → payout 800, remainingCap 3200 (cap 4000)");
    it.todo("cursed sword cap based on insurance value: damage 500 → payout 400, remainingCap 1600");
    it.todo("sword + 3 runes insurance sum 1750: sword damage 500 → payout 400, remainingCap 3100");
    it.todo("successive claims of 1500 on a sword → 1400 (remaining 600), then 600 (remaining 0)");
    it.todo("damage to item not in policy (amulet when only sword insured) → throws");
    it.todo("damage to unknown item type → throws");
    it.todo("more damages of a type than insured (two swords, one insured) → throws");
    it.todo("negative damage amount → throws");
  });

  describe("CLI", () => {
    it.todo("reads scenario JSON from stdin and writes results JSON to stdout");
    it.todo("exits non-zero with error on stderr and no results on stdout for invalid scenario");
  });
});
EOF

