export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: { op: string; items: { type: string }[] }[];
}

const SWORD_BASE_PREMIUM = 100;
const PROCESSING_FEE = 5;

const firstInsuranceSurcharge = (premium: number): number => premium / 10;

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const items = scenario.steps[0].items;
  const basePremium = items.length * SWORD_BASE_PREMIUM;
  const premium =
    basePremium + firstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
  return { results: [{ premium }] };
};

