content.content:
type Item = { type: string };

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: { op: string; items: Item[] }[];
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const PROCESSING_FEE = 5;

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const firstInsuranceSurcharge = (premium: number): number => premium / 10;

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const basePremium = sumBasePremiums(scenario.steps[0].items);
  const premium =
    basePremium + firstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
  return { results: [{ premium }] };
};

