  yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? LOYALTY_DISCOUNT_PERCENT : 0;

// Policy-wide modifiers apply to the base premium; summed as integer percents.
const policyAdjustmentPercent = (yearsWithMHPCO: number): number =>
  FIRST_INSURANCE_PERCENT - loyaltyDiscountPercent(yearsWithMHPCO);

const quotePremium = (items: Item[], yearsWithMHPCO: number): number => {
  const basePremium = sumBasePremiums(items);
  const premium =
    basePremium +
    sumItemSurcharges(items) +
    percentOf(basePremium, policyAdjustmentPercent(yearsWithMHPCO)) +
    PROCESSING_FEE;
  return Math.ceil(premium);
};

export const runScenario = (scenario: Scenario): { results: unknown[] } => ({
  results: [
    {
      premium: quotePremium(
        scenario.steps[0].items,
        scenario.customer.yearsWithMHPCO,
      ),
    },
  ],
});

