const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

const processClaim = (policyItems: Item[], damages: Damage[]) => {
  const cap = CAP_MULTIPLIER * insuranceSum(policyItems);
  const payout = damages.reduce(
    (sum, damage) => sum + damage.amount - DEDUCTIBLE,
    0,
  );
  return { payout, remainingCap: cap - payout };
};

const policyItems = (steps: Step[], policyIndex: number): Item[] =>
  (steps[policyIndex] as QuoteStep).items;

export const runScenario = (scenario: Scenario): { results: unknown[] } => ({
  results: scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      return processClaim(
        policyItems(scenario.steps, step.policy),
        step.incident.damages,
      );
    }
    const isFollowUp = index > 0;
    return {
      premium: quotePremium(
        step.items,
        scenario.customer.yearsWithMHPCO,
        isFollowUp,
      ),
    };
  }),
});

